// HKchat screen builder. Run in Figma Design; each UI part is a native editable layer.
const ICON_BASE64 = '';
const C = {
  dark: '#301542', text: '#37213F', accent: '#A81C7F', pink: '#F553AB',
  pale: '#FFD1E9', muted: '#796B82', border: '#EADCEB', input: '#F9F5F9',
  bubble: '#F7F2F7', white: '#FFFFFF', danger: '#B42318', error: '#FEE4E2',
  canvas: '#F4EFF5', subtle: '#FFF0F8', green: '#1C9B68'
};
const W = 390, H = 844, GAP = 72;
const fontRegular = {family: 'Inter', style: 'Regular'};
const fontBold = {family: 'Inter', style: 'Bold'};
let iconImage = null;
let page;
let built = [];

function rgb(hex) {
  const h = hex.replace('#', '');
  return {r: parseInt(h.slice(0,2),16)/255, g: parseInt(h.slice(2,4),16)/255, b: parseInt(h.slice(4,6),16)/255};
}
function paint(hex) { return [{type:'SOLID', color:rgb(hex)}]; }
function box(parent, name, x, y, w, h, fill, radius=0, border=null, borderWidth=1) {
  const n=figma.createRectangle(); n.name=name; n.resize(w,h); n.x=x; n.y=y;
  n.cornerRadius=radius; n.fills=paint(fill);
  if(border){n.strokes=paint(border); n.strokeWeight=borderWidth;}
  parent.appendChild(n); return n;
}
function circle(parent,name,x,y,d,fill){const n=figma.createEllipse();n.name=name;n.resize(d,d);n.x=x;n.y=y;n.fills=paint(fill);parent.appendChild(n);return n;}
function txt(parent,name,content,x,y,w,h,size=16,color=C.text,bold=false,align='LEFT'){
  const n=figma.createText(); n.name=name; parent.appendChild(n);
  n.fontName=bold?fontBold:fontRegular; n.fontSize=size; n.fills=paint(color);
  n.textAutoResize='NONE'; n.characters=content; n.resize(w,h); n.x=x;n.y=y;
  n.textAlignHorizontal=align; n.textAlignVertical='CENTER';
  return n;
}
function button(parent,name,label,x,y,w,h=44,fill=C.accent){
  box(parent,name+' / nền',x,y,w,h,fill,12);
  txt(parent,name+' / chữ',label,x,y,w,h,15,C.white,true,'CENTER');
}
function input(parent,name,value,x,y,w,h=46){
  box(parent,name+' / nền',x,y,w,h,C.input,12,C.border);
  txt(parent,name+' / nội dung',value,x+14,y+2,w-28,h-4,14,C.muted);
}
function status(parent,dark=false){
  txt(parent,'Thanh trạng thái / giờ','8:21',18,7,50,20,13,dark?C.white:C.text,true);
  txt(parent,'Thanh trạng thái / sóng Wi-Fi pin','▮▮  ◕  ▰',289,7,85,20,12,dark?C.white:C.text,true,'RIGHT');
}
function homeBar(parent){box(parent,'Thanh điều hướng / home indicator',153,830,84,4,C.muted,2);}
function logo(parent,x,y,size){
  if(iconImage){const n=box(parent,'Logo HKchat / appicon',x,y,size,size,C.accent,Math.round(size*.19));n.fills=[{type:'IMAGE',scaleMode:'FILL',imageHash:iconImage.hash}];}
  else {box(parent,'Logo HKchat / nền',x,y,size,size,C.accent,Math.round(size*.19));txt(parent,'Logo HKchat / chữ','HK',x,y,size,size,Math.round(size*.36),C.white,true,'CENTER');}
}
function screen(name,col,row,description){
  const f=figma.createFrame(); f.name=name; f.resize(W,H); f.x=col*(W+GAP);f.y=row*(H+116)+58;
  f.fills=paint(C.white);f.clipsContent=true;page.appendChild(f);built.push(f);
  txt(page,name+' / tiêu đề',name,f.x,f.y-48,W,24,18,C.dark,true);
  txt(page,name+' / mô tả',description,f.x,f.y-23,W,20,12,C.muted);
  return f;
}
function auth(s,mode='login',error=''){
  box(s,'Nền đăng nhập',0,0,W,H,C.dark);status(s,true);
  logo(s,151,135,88);
  txt(s,'Tên ứng dụng','HKchat',40,232,310,50,34,C.white,true,'CENTER');
  txt(s,'Khẩu hiệu','Không gian trò chuyện của riêng bạn',25,281,340,32,13,C.pale,false,'CENTER');
  const register=mode==='register';const cy=(register||error)?339:362;const ch=(register||error)?390:348;
  box(s,'Thẻ biểu mẫu',24,cy,342,ch,C.white,24);
  txt(s,'Tiêu đề biểu mẫu',register?'Tạo tài khoản':'Đăng nhập',43,cy+20,300,39,24,C.text,true);
  let iy=cy+78;
  input(s,'Địa chỉ server','http://10.0.2.2:8070',43,iy,304);iy+=55;
  input(s,'Tên đăng nhập',register?'Tên đăng nhập':'Tên đăng nhập hoặc email',43,iy,304);iy+=55;
  if(register){input(s,'Email','Email',43,iy,304);iy+=55;}
  input(s,'Mật khẩu','Mật khẩu',43,iy,304);iy+=55;
  if(error){box(s,'Thông báo lỗi / nền',43,iy,304,38,C.error,8);txt(s,'Thông báo lỗi / chữ',error,52,iy,286,38,11,C.danger);iy+=43;}
  button(s,'Nút xác thực',register?'Đăng ký':'Đăng nhập',43,iy,304);iy+=52;
  txt(s,'Chuyển biểu mẫu',register?'Đã có tài khoản? Đăng nhập':'Chưa có tài khoản? Đăng ký',43,iy,304,28,13,C.accent,true,'CENTER');
  txt(s,'Server hiện tại','Server: http://10.0.2.2:8070',34,759,322,22,11,C.pale,false,'CENTER');homeBar(s);
}
function header(s,title='HKchat',user='Huy',back=false){
  box(s,'Thanh tiêu đề',0,0,W,91,C.dark);status(s,true);
  txt(s,'Tên màn hình',title,18,36,252,34,22,C.white,true);
  txt(s,'Lời chào','Xin chào, '+user,18,69,210,17,12,C.pale);
  txt(s,'Nút điều hướng',back?'Trở lại':'Đăng xuất',290,47,83,30,13,C.pale,true,'RIGHT');
}
function tabs(s,active){
  box(s,'Thanh tab / nền',0,91,W,54,C.white);
  box(s,'Thanh tab / viền dưới',0,144,W,1,C.border);
  const names=['Kênh','Mọi người','Tìm kiếm'];
  names.forEach((name,i)=>{
    txt(s,'Tab / '+name,name,i*130,100,130,37,14,i===active?C.accent:C.muted,true,'CENTER');
    if(i===active)box(s,'Tab / '+name+' / chỉ báo',i*130,142,130,3,C.pink);
  });
}
function channelRow(s,name,y,kind='public',suffix='›'){
  txt(s,'Kênh / '+name+' / biểu tượng',kind==='public'?'#':'●',19,y+8,30,38,24,C.accent,true);
  txt(s,'Kênh / '+name+' / tên',name,59,y+8,255,38,16,C.text);
  txt(s,'Kênh / '+name+' / mở',suffix,315,y+8,57,38,17,C.muted,false,'RIGHT');
  box(s,'Kênh / '+name+' / đường phân cách',18,y+57,354,1,C.border);
}
function channels(s,variant='default'){
  header(s);tabs(s,0);homeBar(s);
  txt(s,'Mục / Kênh của tôi','Kênh của tôi',18,172,300,30,18,C.text,true);
  channelRow(s,'General',210);
  channelRow(s,'Random',270);
  channelRow(s,'Đồ án chuyên ngành',330,'group');
  txt(s,'Mục / Tạo kênh','Tạo kênh',18,414,300,30,18,C.text,true);
  input(s,'Tên kênh mới',variant==='create'?'phòng-thiết-kế':'Tên kênh mới',18,451,354);
  button(s,'Nút tạo kênh','Tạo kênh',18,507,354);
  txt(s,'Mục / Kênh có thể tham gia','Kênh có thể tham gia',18,581,340,30,18,C.text,true);
  channelRow(s,'hk_test_channel',620,'public',variant==='join'?'Tham gia':'Tham gia');
  if(variant==='create')txt(s,'Gợi ý tạo kênh','Nhấn Tạo kênh để mở hội thoại mới',18,561,354,18,11,C.muted);
  if(variant==='join')box(s,'Điểm nhấn kênh tham gia',13,620,364,58,C.subtle,8,C.pink,2);
}
function people(s){
  header(s);tabs(s,1);homeBar(s);
  txt(s,'Mục / Bắt đầu DM','Bắt đầu tin nhắn trực tiếp',18,172,354,34,18,C.text,true);
  [['Huy','H'],['Khải','K'],['Tân','T'],['Đạt','Đ']].forEach((p,i)=>{
    const y=220+i*72;circle(s,'Thành viên '+p[0]+' / avatar',18,y+4,42,C.pale);
    txt(s,'Thành viên '+p[0]+' / chữ avatar',p[1],18,y+4,42,42,16,C.accent,true,'CENTER');
    txt(s,'Thành viên '+p[0]+' / tên',p[0],72,y+7,240,38,17,C.text);
    txt(s,'Thành viên '+p[0]+' / mở','›',331,y+7,41,38,22,C.muted,false,'RIGHT');
    box(s,'Thành viên '+p[0]+' / viền',18,y+62,354,1,C.border);
  });
}
function bubble(s,name,body,y,mine=false,reply='',reaction=''){
  const x=mine?75:17,w=mine?298:300;
  const lines=body.split('\n').length;
  const bodyH=Math.max(42,lines*21+12); const h=34+bodyH+(reply?35:0)+(reaction?31:0);
  box(s,'Tin '+name+' / bong bóng',x,y,w,h,mine?C.pale:C.bubble,15);
  txt(s,'Tin '+name+' / tác giả',name,x+12,y+8,w-24,18,12,C.accent,true);
  let ty=y+28;
  if(reply){box(s,'Tin '+name+' / vạch trả lời',x+12,ty,2,31,C.accent);txt(s,'Tin '+name+' / trích dẫn',reply,x+20,ty,w-32,31,11,C.muted);ty+=35;}
  txt(s,'Tin '+name+' / nội dung',body,x+12,ty,w-24,bodyH,14,C.text);
  if(reaction){box(s,'Tin '+name+' / cảm xúc / nền',x+12,ty+bodyH-2,48,25,C.white,12,C.border);txt(s,'Tin '+name+' / cảm xúc',reaction,x+12,ty+bodyH-2,48,25,14,C.text,false,'CENTER');}
  return y+h+10;
}
function composer(s,mode='send',value=''){
  box(s,'Thanh soạn tin / nền',0,771,390,63,C.white);
  box(s,'Thanh soạn tin / viền',0,771,390,1,C.border);
  txt(s,'Thanh soạn tin / nội dung',value|| (mode==='edit'?'Sửa tin nhắn...':'Viết tin nhắn...'),16,780,294,44,14,value?C.text:C.muted);
  button(s,'Nút '+(mode==='edit'?'Lưu':'Gửi'),mode==='edit'?'Lưu':'Gửi',323,780,51,42);
  homeBar(s);
}
function chat(s,kind='group',variant='normal'){
  const isDm=kind==='dm'; header(s,isDm?'Khải':'Đồ án chuyên ngành','Huy',true);
  if(isDm){
    let y=123;y=bubble(s,'Khải','Huy ơi, bạn đã xem lại giao diện\nđăng nhập chưa?',y,false);
    y=bubble(s,'Huy','Mình vừa kiểm tra, phần URL server\nđã kết nối được rồi.',y,true);
    y=bubble(s,'Khải','Tốt quá! Chiều nay mình thử thêm\nluồng tin nhắn trực tiếp nhé.',y,false);
    composer(s);return;
  }
  let y=110;
  y=bubble(s,'Huy','Chào cả nhóm! Mọi người dạo này thế\nnào? Mình mở nhóm để bàn đồ án.',y,true);
  y=bubble(s,'Khải','Chào Huy, mình khỏe. Hôm nay mình\nvừa xem lại yêu cầu MVP.',y,false);
  y=bubble(s,'Tân','Mình cũng ổn. Cả nhóm định chốt\nchức năng nào cho buổi demo?',y,false);
  y=bubble(s,'Đạt','Mình nghĩ nên tập trung đăng ký,\nđăng nhập, kênh, DM và tìm kiếm.',y,false,'',variant==='reaction'?'👍 2':'');
  if(variant==='reply'){
    box(s,'Thanh trả lời / nền',0,726,390,45,C.subtle);
    txt(s,'Thanh trả lời / nội dung','Trả lời Tân: Cả nhóm định chốt...',16,733,328,31,12,C.text);
    txt(s,'Thanh trả lời / hủy','×',348,733,26,31,20,C.accent,true,'CENTER');
    composer(s,'send','Mình sẽ chuẩn bị bản demo');
  }else if(variant==='edit'){
    box(s,'Thanh sửa / nền',0,726,390,45,C.subtle);
    txt(s,'Thanh sửa / nội dung','Sửa: Mình nghĩ nên tập trung...',16,733,328,31,12,C.text);
    txt(s,'Thanh sửa / hủy','×',348,733,26,31,20,C.accent,true,'CENTER');
    composer(s,'edit','Mình nghĩ nên tập trung vào demo');
  }else{
    if(variant==='reaction'){
      box(s,'Bộ chọn cảm xúc / nền',32,691,326,55,C.white,13,C.border);
      ['👍','❤️','😂','🎉'].forEach((e,i)=>txt(s,'Bộ chọn cảm xúc / '+e,e,51+i*75,699,52,38,22,C.text,false,'CENTER'));
    }
    composer(s);
  }
}
function overlay(s,title,subtitle,actions){
  box(s,'Lớp phủ / nền tối',0,0,W,H,'#16101B').opacity=0.56;
  const top=actions.length>3?325:367;
  box(s,'Hộp thoại / nền',25,top,340,actions.length>3?232:194,C.white,18);
  txt(s,'Hộp thoại / tiêu đề',title,45,top+22,300,32,18,C.text,true,'CENTER');
  txt(s,'Hộp thoại / mô tả',subtitle,45,top+58,300,47,13,C.muted,false,'CENTER');
  const buttonY=top+111;
  actions.forEach((a,i)=>{
    const x=actions.length>3?47+(i%2)*151:47+i*101;
    const y=actions.length>3?buttonY+Math.floor(i/2)*49:buttonY;
    button(s,'Hộp thoại / '+a,a,x,y,actions.length>3?139:94,38,a==='Xóa'?C.danger:C.accent);
  });
}
function search(s,withResults=false){
  header(s);tabs(s,2);homeBar(s);
  txt(s,'Mục / Tìm tin nhắn','Tìm tin nhắn',18,173,354,31,18,C.text,true);
  input(s,'Từ khóa tìm kiếm',withResults?'MVP':'Nhập từ khóa',18,215,354);
  button(s,'Nút tìm kiếm','Tìm kiếm',18,272,354);
  if(withResults){
    [['Khải','Hôm nay mình vừa xem lại yêu cầu MVP\ncủa HKchat.'],['Đạt','Nên tập trung các chức năng MVP\ncho buổi demo.'],['Huy','Mình sẽ kiểm tra phần đăng nhập\ntrong bản MVP.']].forEach((r,i)=>{
      const y=348+i*111;box(s,'Kết quả '+(i+1)+' / nền',18,y,354,98,C.bubble,12);
      txt(s,'Kết quả '+(i+1)+' / tác giả',r[0],31,y+9,320,19,12,C.accent,true);
      txt(s,'Kết quả '+(i+1)+' / nội dung',r[1],31,y+30,320,55,14,C.text);
    });
  }else txt(s,'Hướng dẫn tìm kiếm','Nhập từ khóa để tìm các tin nhắn\ntrong kênh và DM.',32,355,326,66,14,C.muted,false,'CENTER');
}
function swatches(){
  const x=0,y=-160;txt(page,'Hệ màu / tiêu đề','HKchat / màu giao diện',x,y,800,40,27,C.dark,true);
  [['Dark',C.dark],['Accent',C.accent],['Pink',C.pink],['Pale',C.pale],['Text',C.text],['Border',C.border]].forEach((item,i)=>{
    const sx=i*182;box(page,'Màu '+item[0],sx,y+52,160,42,item[1],8);
    txt(page,'Mã '+item[0],item[0]+'  '+item[1],sx,y+100,165,25,12,C.text);
  });
}
async function main(){
  await Promise.all([figma.loadFontAsync(fontRegular),figma.loadFontAsync(fontBold)]);
  try{const bytes=Uint8Array.from(atob(ICON_BASE64),c=>c.charCodeAt(0));iconImage=figma.createImage(bytes);}catch(e){iconImage=null;}
  page=(figma.currentPage.name==='HKchat – Thiết kế đầy đủ (editable)' && figma.currentPage.children.length===0)
    ? figma.currentPage : figma.createPage();
  page.name='HKchat – Thiết kế đầy đủ (editable)';
  await figma.setCurrentPageAsync(page);
  swatches();
  let s;
  s=screen('01 / Đăng nhập và URL server',0,0,'Xác thực và cấu hình API local');auth(s);
  s=screen('02 / Đăng ký tài khoản',1,0,'Tạo tên đăng nhập, email, mật khẩu');auth(s,'register');
  s=screen('03 / Lỗi địa chỉ server',2,0,'Trạng thái kiểm tra kết nối');auth(s,'login','Không thể kết nối đến server');
  s=screen('04 / Danh sách kênh',3,0,'Kênh cá nhân, kênh nhóm, kênh công khai');channels(s);
  s=screen('05 / Tạo kênh mới',0,1,'Nhập tên kênh rồi tạo');channels(s,'create');
  s=screen('06 / Tham gia kênh',1,1,'Mở kênh công khai có thể tham gia');channels(s,'join');
  s=screen('07 / Mọi người và bắt đầu DM',2,1,'Danh sách thành viên nội bộ');people(s);
  s=screen('08 / Tin nhắn trực tiếp',3,1,'Hội thoại riêng giữa Huy và Khải');chat(s,'dm');
  s=screen('09 / Hội thoại nhóm',0,2,'Huy, Khải, Tân, Đạt bàn về đồ án');chat(s);
  s=screen('10 / Trả lời tin nhắn',1,2,'Trích dẫn tin nhắn và gửi trả lời');chat(s,'group','reply');
  s=screen('11 / Sửa tin nhắn',2,2,'Sửa nội dung tin của chính mình');chat(s,'group','edit');
  s=screen('12 / Thả cảm xúc',3,2,'Chọn emoji và xem lượt phản ứng');chat(s,'group','reaction');
  s=screen('13 / Tùy chọn tin nhắn',0,3,'Nhấn giữ tin của chính mình');chat(s);overlay(s,'Tin nhắn','Chọn thao tác với tin nhắn',['Trả lời','Sửa','Thêm','Hủy']);
  s=screen('14 / Xác nhận xóa tin',1,3,'Xóa tin nhắn của chính mình');chat(s);overlay(s,'Xóa tin nhắn?','Không thể hoàn tác',['Hủy','Xóa']);
  s=screen('15 / Tìm kiếm',2,3,'Nhập từ khóa trong nội dung chat');search(s);
  s=screen('16 / Kết quả tìm kiếm',3,3,'Danh sách các tin khớp từ khóa');search(s,true);
  s=screen('17 / Mở hội thoại từ kết quả',0,4,'Quay lại kênh chứa tin đã tìm');chat(s);
  s=screen('18 / Đăng xuất',1,4,'Xác nhận kết thúc phiên đăng nhập');channels(s);overlay(s,'Đăng xuất','Bạn muốn đăng xuất khỏi HKchat?',['Hủy','Đăng xuất']);
  figma.currentPage.selection=[];
  figma.viewport.scrollAndZoomIntoView(built);
  figma.notify('Đã tạo '+built.length+' màn hình HKchat với các thành phần chỉnh sửa riêng.');
  figma.closePlugin();
}
main().catch(e=>{console.error(e);figma.notify('Lỗi tạo màn hình: '+String(e),{error:true,timeout:30000});figma.closePlugin();});
